import struct,re,subprocess
d=open('/challenge/chal/food','rb').read()
def va(a): return a-0x403640+0x3640
tab=struct.unpack('<3497i',d[va(0x403740):va(0x403740)+0x36a4]);N=len(tab)
tg=d[va(0x403660):va(0x403660)+74]
out=subprocess.run("objdump -d -M intel --disassemble=_Z6verifyNSt7__cxx1112basic_stringIcSt11char_traitsIcESaIcEEE /challenge/chal/food",shell=True,capture_output=True,text=True).stdout
init=[]
for m in re.finditer(r'mov\s+BYTE PTR \[rbp-0x([0-9a-f]+)\],0x([0-9a-f]+)',out):
    o=int(m.group(1),16)
    if 0x47<=o<=0x90: init.append((-o,int(m.group(2),16)))
init=bytes(v for _,v in sorted(init));print(len(init))
mid=list(tg)
for i in range(5,74):
    x=0
    for j in range(300): x^=((j<<5)&0xff)^(tg[i-5]==0x6e)
    mid[i]=tg[i]^x
for L in range(1,80):
    sol=[]
    ok=True
    for p in range(L):
        c=[]
        for ch in range(32,127):
            good=True
            for i in range(p,74,L):
                v=init[i]^ch if i<L else init[i]
                if ((v^tab[(ch+tab[(i*10+12)%N])%N])&0xff)!=mid[i]: good=False;break
            if good:c.append(ch)
        if not c: ok=False;break
        sol.append(c)
    if ok: print(L,sol)

